rows.source:
outer {
  inner {
    a: hello
    b: world
  }
  c: outside
}

users: { shape: sql_table }
users.columns: [id, name, email]
orders: { shape: sql_table }
orders.columns: [id, user_id, total]

db: { shape: cylinder; fill: #e3f2fd; stroke: #1976d2 }
person: { shape: person; fill: #fff3e0 }
box {
  fill: rgba(255, 0, 0, 0.1)
}

diagram: { shape: sequence_diagram }
diagram.participants: [Alice, Bob, Server]
diagram.messages: ["Alice->Bob: Hello", "Bob->Server: Query", "Server->Bob: Result"]

digraph {
  A [shape=record, label="{<f0>hello | <f1>world}"];
  B [shape=record, label="{<top>top | bottom}"];
  A:f0 -> B:top;
}

digraph {
  A [label="<b>Bold</b> and <i>italic</i>"];
  B [label="<table><tr><td>Cell 1</td><td>Cell 2</td></tr></table>"];
  A -> B;
}

digraph {
  subgraph cluster_0 {
    label = "Database Servers";
    db1;
    db2;
  }
  app -> db1;
  app -> db2;
}

digraph {
  subgraph { rank=same; A; B; C; }
  A -> D;
  B -> D;
  C -> D;
}

digraph {
  A [shape=box];
  B [shape=box];
  A:e -> B:w;
  A:s -> C;
}

digraph {
  "Node with spaces" -> "Another \"quoted\" node";
  "Node with spaces" [label="Label with | pipe"];
}

nwdiag {
  network dmz {
    address = "10.0.1.0/24"
    web [stack];
  }
  network lan {
    address = "10.0.2.0/24"
    db [shape=cylinder];
  }
  dmz -- lan;
}

nwdiag {
  network wan {
    address = "203.0.113.0/24"
    router;
  }
  network lan {
    address = "192.168.1.0/24"
    router;
    workstation;
  }
  router -- workstation;
}

nwdiag {
  network office {
    address = "10.10.0.0/16"
    group servers {
      web;
      app;
    }
    group clients {
      pc1;
      pc2;
    }
    servers -- clients;
  }
}

nwdiag {
  network prod {
    address = "10.1.0.0/24"
    web [color="#ff6600"];
    db [color="#3399ff", shape=cylinder];
  }
  network dev {
    address = "10.2.0.0/24"
    sandbox [color="#99cc66", style=dashed];
  }
  prod -- dev;
}

nwdiag {
  network office {
    address = "172.16.0.0/12"
    "Main Router" [shape=router];
    "Firewall (Palo Alto)" [shape=firewall];
    "DB Server (SQL)" [shape=cylinder];
  }
  "Main Router" -- "Firewall (Palo Alto)" -- "DB Server (SQL)";
}

nwdiag {
  network corp {
    address = "10.0.0.0/8"
    app;
  }
  network partner {
    address = "10.100.0.0/16"
    api;
  }
  corp peer partner;
}
